        groups = []
        group = ""
        count = 0
        for char in s:
            if char == '(':
                count += 1
                if count == 1:
                    group += char
            elif char == ')':
                count -= 1
                if count == 0:
                    group += char
                    groups.append(group)
                    group = ""
            else:
